// Keep Android launcher resources generated by Tauri's official icon CLI.
import { cpSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { spawnSync } from 'node:child_process'

const root = dirname(dirname(fileURLToPath(import.meta.url)))
const output = join(root, '.local', 'android', 'icons')
const generated = spawnSync(
  process.execPath,
  [
    join(root, 'scripts', 'tauri.mjs'),
    'icon',
    join(root, 'docs', 'app-icon.png'),
    '--output',
    output
  ],
  { cwd: root, stdio: 'inherit' }
)
if (generated.error) throw generated.error
if (generated.status !== 0) process.exit(generated.status ?? 1)
const resources = join(root, 'app', 'src-tauri', 'gen', 'android', 'app', 'src', 'main', 'res')
mkdirSync(resources, { recursive: true })
cpSync(join(output, 'android'), resources, { recursive: true })

// AdaptiveIconDrawable displays the inner 72dp of a 108dp layer. Keep the
// desktop artwork's proportions by fitting the full source into those 72dp.
// Fractions also preserve this ratio when launchers render at different sizes.
const adaptiveDirectory = join(resources, 'mipmap-anydpi-v26')
const launcher = readFileSync(join(adaptiveDirectory, 'ic_launcher.xml'), 'utf8').replace(
  '<foreground android:drawable="@mipmap/ic_launcher_foreground"/>',
  `<foreground>
    <inset
      android:drawable="@mipmap/ic_launcher_foreground"
      android:insetLeft="16.666667%"
      android:insetTop="16.666667%"
      android:insetRight="16.666667%"
      android:insetBottom="16.666667%" />
  </foreground>`
)
if (!launcher.includes('android:insetLeft=')) throw new Error('Unexpected adaptive icon output')
for (const name of ['ic_launcher.xml', 'ic_launcher_round.xml']) {
  writeFileSync(join(adaptiveDirectory, name), launcher)
}
